options.css:
.v-quiet-top { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-4); }
.v-quiet-place { min-width: 0; }
.v-quiet .flag { margin-top: var(--space-3); }
.v-quiet-temp { margin: 0; font-size: var(--text-4xl); }
.v-quiet-line { margin-top: var(--space-5); padding-top: var(--space-4); border-top: 1px solid var(--color-line); font-size: var(--text-sm); color: var(--color-ink-2); }

.v-open { margin: var(--space-5) var(--space-4) 0; padding: var(--space-4) var(--space-1) 0; border-top: 2px solid var(--color-ink); }
.v-open-top { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--space-2); }
.v-open-temp { margin: var(--space-5) 0 0; font-size: var(--text-5xl); }
.v-open-readings { margin-top: var(--space-5); }
.v-open-window { margin-top: var(--space-4); padding-bottom: var(--space-5); border-bottom: 1px solid var(--color-line); }

.v-verdict-top { display: flex; flex-direction: column; align-items: flex-start; gap: var(--space-2); }
.v-verdict-line { margin-top: var(--space-6); font-size: var(--text-2xl); }
.v-verdict-why { margin-top: var(--space-2); font-size: var(--text-sm); color: var(--color-ink-2); }
.v-verdict-grid { display: grid; grid-template-columns: 1.3fr 1fr 1fr 1fr; gap: var(--space-3); margin: var(--space-6) 0 0; padding-top: var(--space-4); border-top: 1px solid var(--color-line); }
.v-verdict-temp dd { font-family: var(--font-display); font-stretch: 125%; font-weight: var(--weight-black); font-size: var(--text-xl); line-height: 1; }
